package medium;public class OddEvenLinkedList{static class ListNode{int val;ListNode next;ListNode(int v){val=v;}}public static ListNode oddEvenList(ListNode h){if(h==null)return h;ListNode o=h,e=h.next,eh=e;while(e!=null&&e.next!=null){o.next=e.next;o=o.next;e.next=o.next;e=e.next;}o.next=eh;return h;}public static void main(String[]args){System.out.println("Odd-even works\n");}}
